/**
 * 负责 狼人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { roleName, text } from "@ai-werewolf-arena/game-text";
/** 文件说明：狼人角色 profile。 */
import { Camp, Role } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";
import { WOLF_LLM_REPAIR_PACK } from "./llm_repair";
import { WOLF_NIGHT_STAGES } from "./night_stages";
import { WOLF_TOOL_SPECS, WOLF_STAGE_DIRECTIVES } from "./tool_specs";
import { WOLF_VALIDATION_RULES } from "./validation_rules";
import { isMistRavenBoard, mistKnifeTargets } from "../mist_raven/night_frame";

/** 狼人角色配置。 */
export const WOLF_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Wolf,
    camp: Camp.Wolf,
    label: roleName("wolf"),
    skillBrief: text("zh-CN", "role.wolf.brief"),
  },
  runtime: {
    canSelfDestruct: true,
    wolfTeam: { recognizedByPack: true, recognizes: "pack", canChat: true, canVoteForKill: true },
    toolSpecs: WOLF_TOOL_SPECS,
    stageDirectives: WOLF_STAGE_DIRECTIVES,
    validationRules: WOLF_VALIDATION_RULES,
    nightStages: WOLF_NIGHT_STAGES,
    llmRepair: WOLF_LLM_REPAIR_PACK,
    baselineAction: (
      _roleComp,
      request,
      _pickAliveNotSelf,
      pickAliveByCamp,
      locale = "zh-CN",
      world,
    ) => {
      if (request.allowedTools.includes("speak_to_wolves")) {
        return {
          name: "speak_to_wolves",
          args: {
            text: text(locale, "fallback.wolf_chat"),
            end_chat: false,
          },
        };
      }
      if (request.allowedTools.includes("kill_vote")) {
        const circle = world && isMistRavenBoard(world) ? mistKnifeTargets(world) : null;
        if (circle !== null) {
          const target = circle[0] ?? null;
          return { name: "kill_vote", args: { target_id: target, abstain: target === null } };
        }
        const target = pickAliveByCamp("good");
        if (target !== null) {
          return { name: "kill_vote", args: { target_id: target, abstain: false } };
        }
        return { name: "kill_vote", args: { target_id: null, abstain: true } };
      }
      if (request.allowedTools.includes("self_destruct")) {
        // 自爆属于高风险动作：fallback 不应在“可选中断窗口”默认触发。
        return null;
      }
      return null;
    },
  },
  presentation: nativeRolePresentation("wolf"),
};

/**
 * 负责 觉醒隐狼 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Camp, Role } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { WOLF_ROLE_PROFILE } from "../wolf/profile";
import { DEATH_SHOT_TOOL_SPECS, DEATH_SHOT_REPAIR, validateDeathShot } from "../death_shot";
import {
  ROLE_INSPECTION_TOOL,
  roleInspectionTargets,
  validateRoleInspection,
} from "../role_inspection/rules";
import { findNightAbility } from "../abilities";
import { numberOrNull } from "../../llm/helpers";
import { canAwakenedKnife } from "./inheritance";
import { awakenedDeathHook } from "./death_hook";
import { AWAKENED_NIGHT_STAGES } from "./night_stages";
import { AWAKENED_TOOL_SPECS } from "./tool_specs";
import { AWAKENED_TOOL_NAMES, AWAKENED_VALIDATION_RULES } from "./rules";
import {
  freshAwakenedState,
  getAwakenedState,
  projectAwakenedState,
  setAwakenedState,
} from "./state";

export const AWAKENED_HIDDEN_WOLF_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...WOLF_ROLE_PROFILE.metadata,
    role: Role.AwakenedHiddenWolf,
    camp: Camp.Wolf,
    maxCount: 1,
    supportedBoardRoles: [
      Role.AwakenedHiddenWolf,
      Role.Wolf,
      Role.MirrorGirl,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Villager,
    ],
    label: roleName("awakened_hidden_wolf"),
    skillBrief: text("zh-CN", "role.awakened_hidden_wolf.brief"),
  },
  runtime: {
    ...WOLF_ROLE_PROFILE.runtime,
    canSelfDestruct: false,
    init: (role) => {
      if (!getAwakenedState(role)) setAwakenedState(role, freshAwakenedState());
    },
    wolfTeam: (role, world) => ({
      recognizedByPack: false,
      recognizes: "none",
      canChat: false,
      canVoteForKill: canAwakenedKnife(role, world),
    }),
    inspectionLabels: (role) => ({
      camp: Camp.Wolf,
      role: getAwakenedState(role)?.learned?.role ?? Role.AwakenedHiddenWolf,
    }),
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    possibleNightAbilities: ["role_check"],
    toolSpecs: [
      ...WOLF_ROLE_PROFILE.runtime.toolSpecs!.filter((spec) => spec.name === "kill_vote"),
      ...AWAKENED_TOOL_SPECS,
      ROLE_INSPECTION_TOOL,
      ...DEATH_SHOT_TOOL_SPECS,
    ],
    nightStages: [...AWAKENED_NIGHT_STAGES, ...WOLF_ROLE_PROFILE.runtime.nightStages!],
    validationRules: {
      ...WOLF_ROLE_PROFILE.runtime.validationRules,
      ...AWAKENED_VALIDATION_RULES,
      inspect_role: validateRoleInspection,
      shoot: (ctx) => {
        const learned = getAwakenedState(ctx.role)?.learned,
          gun = learned?.skill;
        return validateDeathShot(
          ctx,
          ctx.role.role === Role.AwakenedHiddenWolf &&
            ctx.role.camp === Camp.Wolf &&
            learned?.role === Role.Hunter &&
            learned.activationNight != null &&
            gun?.kind === "hunter" &&
            gun.armed &&
            gun.canShoot,
        );
      },
    },
    deathHook: awakenedDeathHook,
    llmRepair: {
      coerce: {
        ...WOLF_ROLE_PROFILE.runtime.llmRepair?.coerce,
        ...DEATH_SHOT_REPAIR.coerce,
        ...Object.fromEntries(
          [...AWAKENED_TOOL_NAMES, "inspect_role"].map((name) => [
            name,
            (args: Record<string, unknown>) => {
              if (args.target_id === null && ["awakened_guard", "awakened_attack"].includes(name))
                return { target_id: null };
              const target = numberOrNull(args.target_id);
              return target === null ? null : { target_id: target };
            },
          ]),
        ),
      },
    },
    baselineAction: (role, request, pick, byCamp, locale, world) => {
      if (request.allowedTools.includes("awakened_mimic")) {
        const target = pick();
        return target === null ? null : { name: "awakened_mimic", args: { target_id: target } };
      }
      if (request.allowedTools.includes("awakened_poison")) {
        const target = byCamp("good");
        return target === null ? null : { name: "awakened_poison", args: { target_id: target } };
      }
      if (request.allowedTools.includes("awakened_guard"))
        return { name: "awakened_guard", args: { target_id: null } };
      if (request.allowedTools.includes("awakened_attack"))
        return { name: "awakened_attack", args: { target_id: byCamp("good") } };
      if (request.allowedTools.includes("inspect_role")) {
        const ability = findNightAbility(role, "role_check", request.context.ability_id),
          target =
            world && ability
              ? roleInspectionTargets(world, request.actorId, ability.state)[0]
              : undefined;
        return target === undefined ? null : { name: "inspect_role", args: { target_id: target } };
      }
      if (request.allowedTools.includes("shoot"))
        return { name: "shoot", args: { target_id: byCamp("good") } };
      return WOLF_ROLE_PROFILE.runtime.baselineAction!(role, request, pick, byCamp, locale, world);
    },
  },
  presentation: nativeRolePresentation("awakened_hidden_wolf"),
};

/**
 * 负责 恶夜骑士 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Role, WinCondition } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { WOLF_ROLE_PROFILE } from "../wolf/profile";
import { EVIL_KNIGHT_POLICY, freshEvilKnightState, getEvilKnightState } from "./state";
import { EVIL_KNIGHT_FRAME_STAGE } from "./night_frame";
const parameters = z.strictObject({
  policy: z.literal(EVIL_KNIGHT_POLICY).default(EVIL_KNIGHT_POLICY),
  shotPolicy: z.enum(["night_shot_immune", "hunter_shot_bypasses"]).default("night_shot_immune"),
});
export const EVIL_KNIGHT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...WOLF_ROLE_PROFILE.metadata,
    role: Role.EvilKnight,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.EvilKnight,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
    ],
    label: roleName("evil_knight"),
    skillBrief: text("zh-CN", "role.evil_knight.brief"),
  },
  runtime: {
    ...WOLF_ROLE_PROFILE.runtime,
    canSelfDestruct: false,
    toolSpecs: (WOLF_ROLE_PROFILE.runtime.toolSpecs ?? []).filter(
      (spec) => spec.name !== "self_destruct" && spec.name !== "self_destruct_with_target",
    ),
    init: (role, ctx) => {
      role.privateState.evilKnight = freshEvilKnightState(
        parameters.parse(ctx.boardConfig?.evilKnight ?? {}).shotPolicy,
      );
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, evilKnight: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.evilKnight ?? {}),
    },
    nightStages: [EVIL_KNIGHT_FRAME_STAGE, ...(WOLF_ROLE_PROFILE.runtime.nightStages ?? [])],
  },
  presentation: nativeRolePresentation("evil_knight"),
};

/**
 * 负责 寻香魅影／觉醒预言家 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Camp, Role, WinCondition } from "../../../../core/domain/identity";
import type { NativeRoleContributions, RoleRuntimeContribution } from "../contracts";
import { WOLF_ROLE_PROFILE } from "../wolf/profile";
import { freshFragrantState, FRAGRANT_PAIR_POLICY } from "./state";
import { installPairStateSlot } from "./pair-state-slot";
import { fragrantKnownWolfIds, fragrantRoleKnifeEligible } from "./authority";
import { canSubmitFragrantPairChoice } from "./requests";
import { FRAGRANT_BIND_STAGE, PAIR_INSPECTION_STAGE } from "./night_stages";
const policy = z.strictObject({
  policy: z.literal(FRAGRANT_PAIR_POLICY).default(FRAGRANT_PAIR_POLICY),
});
const common = {
  metadata: {
    maxCount: 1,
    supportedBoardRoles: [
      Role.FragrantPhantom,
      Role.AwakenedSeer,
      Role.Wolf,
      Role.Villager,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
    ],
    supportedWinConditions: [WinCondition.SlaughterSide],
  },
  runtime: {
    configuration: {
      schema: policy,
      defaults: policy.parse({}),
      apply: (
        config: Parameters<NonNullable<RoleRuntimeContribution["configuration"]>["apply"]>[0],
        value: unknown,
      ) => ({ ...config, fragrantPairSeer: policy.parse(value) }),
      serialize: (
        config: Parameters<NonNullable<RoleRuntimeContribution["configuration"]>["serialize"]>[0],
      ) => policy.parse(config.fragrantPairSeer ?? {}),
    },
  },
};
const pairSchema = {
  type: "array",
  items: { type: "integer", minimum: 1 },
  minItems: 2,
  maxItems: 2,
  uniqueItems: true,
};
export const FRAGRANT_PHANTOM_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...WOLF_ROLE_PROFILE.metadata,
    ...common.metadata,
    role: Role.FragrantPhantom,
    camp: Camp.Wolf,
    label: roleName("fragrant_phantom"),
    skillBrief: text("zh-CN", "role.fragrant_phantom.brief"),
  },
  runtime: {
    ...WOLF_ROLE_PROFILE.runtime,
    ...common.runtime,
    canSelfDestruct: false,
    wolfTeam: (role, world) => ({
      recognizedByPack: false,
      recognizes: "none",
      canChat: false,
      canVoteForKill: !!world && fragrantRoleKnifeEligible(world, role),
    }),
    knownTeammates: (role, world) => fragrantKnownWolfIds(world, role),
    init: (role) => {
      role.privateState.fragrant = freshFragrantState();
    },
    toolSpecs: [
      ...(WOLF_ROLE_PROFILE.runtime.toolSpecs ?? []).filter((s) => s.name === "kill_vote"),
      {
        name: "bind_fragrant_pair",
        parameters: {
          type: "object",
          properties: { target_ids: { ...pairSchema, type: ["array", "null"] } },
          required: ["target_ids"],
          additionalProperties: false,
        },
        argHint: 'bind_fragrant_pair args: {"target_ids":[number,number]|null}',
        userPromptHintKey: "action.bind_fragrant_pair.hint",
      },
    ],
    stageDirectives: [
      ...(WOLF_ROLE_PROFILE.runtime.stageDirectives ?? []),
      {
        match: (tools) => tools.length === 1 && tools[0] === "bind_fragrant_pair",
        messageKey: "action.bind_fragrant_pair.directive",
        text: text("zh-CN", "action.bind_fragrant_pair.directive"),
      },
    ],
    validationRules: {
      ...WOLF_ROLE_PROFILE.runtime.validationRules,
      bind_fragrant_pair: ({ world, actorId, phase, day, fragrantPairScope, toolCall }) =>
        canSubmitFragrantPairChoice(world, actorId, phase, day ?? 0, fragrantPairScope, toolCall)
          ? null
          : { code: RuleError.FragrantPairUnavailable },
    },
    nightStages: [...(WOLF_ROLE_PROFILE.runtime.nightStages ?? []), FRAGRANT_BIND_STAGE],
    baselineAction: (role, request, ...rest) =>
      request.allowedTools.includes("bind_fragrant_pair")
        ? { name: "bind_fragrant_pair", args: { target_ids: null } }
        : (WOLF_ROLE_PROFILE.runtime.baselineAction?.(role, request, ...rest) ?? null),
  },
  presentation: nativeRolePresentation("fragrant_phantom"),
};
export const AWAKENED_SEER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...common.metadata,
    role: Role.AwakenedSeer,
    camp: Camp.Good,
    goodSide: "god",
    label: roleName("awakened_seer"),
    skillBrief: text("zh-CN", "role.awakened_seer.brief"),
  },
  runtime: {
    ...common.runtime,
    canSelfDestruct: false,
    init: (role) => {
      installPairStateSlot(role);
    },
    toolSpecs: [
      {
        name: "check_pair",
        parameters: {
          type: "object",
          properties: { target_ids: pairSchema },
          required: ["target_ids"],
          additionalProperties: false,
        },
        argHint: 'check_pair args: {"target_ids":[number,number]}',
        userPromptHintKey: "action.check_pair.hint",
      },
    ],
    stageDirectives: [
      {
        match: (tools) => tools.length === 1 && tools[0] === "check_pair",
        messageKey: "action.check_pair.directive",
        text: text("zh-CN", "action.check_pair.directive"),
      },
    ],
    validationRules: {
      check_pair: ({ world, actorId, phase, day, fragrantPairScope, toolCall }) =>
        canSubmitFragrantPairChoice(world, actorId, phase, day ?? 0, fragrantPairScope, toolCall)
          ? null
          : { code: RuleError.FragrantPairUnavailable },
    },
    nightStages: [PAIR_INSPECTION_STAGE],
    baselineAction: (_role, request) => {
      const ids = request.context.pair_check_candidates;
      return request.allowedTools.includes("check_pair") && ids && ids.length >= 2
        ? { name: "check_pair", args: { target_ids: [ids[0]!, ids[1]!] } }
        : null;
    },
  },
  presentation: nativeRolePresentation("awakened_seer"),
};

/**
 * 负责 石像鬼 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { inspectionConfiguration, renderInspectionPolicy } from "../role_inspection/policies";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { inspectionLabel } from "@ai-werewolf-arena/game-presentation";
import { Role } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getGargoyleState, setGargoyleState } from "./state";
import { getRoleInspectionState, setRoleInspectionState } from "../role_inspection/ports";
import { WOLF_ROLE_PROFILE } from "../wolf/profile";
import { numberOrNull } from "../../llm/helpers";
import { canGargoyleKnife } from "./inheritance";
import { ROLE_INSPECTION_STAGE } from "../role_inspection/night_stages";

import {
  ROLE_INSPECTION_TOOL,
  validateRoleInspection,
  roleInspectionTargets,
} from "../role_inspection/rules";

export const GARGOYLE_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...WOLF_ROLE_PROFILE.metadata,
    role: Role.Gargoyle,
    maxCount: 1,
    label: roleName("gargoyle"),
    skillBrief: text("zh-CN", "role.gargoyle.brief"),
  },
  runtime: {
    ...WOLF_ROLE_PROFILE.runtime,
    canSelfDestruct: false,
    init: (role, ctx) => {
      setGargoyleState(role, { hasInheritedKnife: false });
      setRoleInspectionState(role, {
        lastTarget: null,
        lastDay: null,
        history: [],
        ...(ctx.boardConfig?.gargoyle?.inspectionPolicy &&
        ctx.boardConfig.gargoyle.inspectionPolicy !== "awa_unique_required_v1"
          ? { inspectionPolicy: ctx.boardConfig.gargoyle.inspectionPolicy }
          : {}),
      });
    },
    wolfTeam: (role, world) => ({
      recognizedByPack: false,
      recognizes: "none",
      canChat: false,
      canVoteForKill: canGargoyleKnife(role, world),
    }),
    configuration: inspectionConfiguration("gargoyle", "awa_unique_required_v1"),
    nightStages: [ROLE_INSPECTION_STAGE, ...WOLF_ROLE_PROFILE.runtime.nightStages!],
    possibleNightAbilities: ["role_check"],
    toolSpecs: [
      ...WOLF_ROLE_PROFILE.runtime.toolSpecs!.filter((spec) => spec.name === "kill_vote"),
      ROLE_INSPECTION_TOOL,
    ],
    validationRules: {
      ...WOLF_ROLE_PROFILE.runtime.validationRules,
      inspect_role: validateRoleInspection,
    },
    llmRepair: {
      coerce: {
        ...WOLF_ROLE_PROFILE.runtime.llmRepair?.coerce,
        inspect_role: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
    baselineAction: (role, request, pick, byCamp, locale, world) => {
      if (request.allowedTools.includes("inspect_role")) {
        const state = getRoleInspectionState(role, request.context.ability_id),
          target = world && state ? roleInspectionTargets(world, request.actorId, state)[0] : null;
        return target === null || target === undefined
          ? null
          : { name: "inspect_role", args: { target_id: target } };
      }
      return WOLF_ROLE_PROFILE.runtime.baselineAction!(role, request, pick, byCamp, locale, world);
    },
  },
  presentation: nativeRolePresentation("gargoyle"),
};

/**
