            "mechanical_poison",
            "mechanical_guard",
            "mechanical_attack",
          ].map((name) => [
            name,
            (args: Record<string, unknown>) => {
              if (
                args.target_id === null &&
                ["mechanical_guard", "mechanical_attack"].includes(name)
              )
                return { target_id: null };
              const target = numberOrNull(args.target_id);
