} from "./night_frame";

const parameters = z.strictObject({
  policy: z.literal(MIST_RAVEN_POLICY).default(MIST_RAVEN_POLICY),
});
const supported = [
  Role.Wolf,
  Role.RavenClawWolf,
  Role.Villager,
  Role.Alchemist,
  Role.Seer,
  Role.Dreamer,
  Role.Idiot,
];
const configuration = {
